mod module_bindings;

use module_bindings::*;
use spacetimedb_sdk::__codegen::InternalError;
use spacetimedb_sdk::{
    DbConnectionBuilder, DbContext, Event, Identity, ReducerEvent, Table, TableAccessor, TableWithPrimaryKey, Timestamp,
};

// Row types and their fields.
fn rows(u: User, m: Message) -> (Identity, Option<String>, bool, Identity, Timestamp, String) {
    (u.identity, u.name, u.online, m.sender, m.sent, m.text)
}

// Row derives.
fn row_derives(u: &User, m: &Message) -> bool {
    format!("{u:?}{m:?}").is_empty() || (u.clone() == *u && m.clone() == *m)
}

// Every table item, by name.
fn tables(ctx: &DbConnection) {
    let users: UserTableHandle<'_> = ctx.db.user();
    let messages: MessageTableHandle<'_> = ctx.db.message();
    let _: u64 = users.count() + messages.count();
    let ins: UserInsertCallbackId = users.on_insert(|_ctx: &EventContext, _row: &User| {});
    users.remove_on_insert(ins);
    let del: UserDeleteCallbackId = users.on_delete(|_ctx: &EventContext, _row: &User| {});
    users.remove_on_delete(del);
    let upd: UserUpdateCallbackId = users.on_update(|_ctx: &EventContext, _old: &User, _new: &User| {});
    users.remove_on_update(upd);
    let m_ins: MessageInsertCallbackId = messages.on_insert(|_ctx, _row| {});
    messages.remove_on_insert(m_ins);
    let _: MessageDeleteCallbackId = messages.on_delete(|_ctx, _row| {});
    let unique: UserIdentityUnique<'_> = users.identity();
    let _: Option<User> = unique.find(&Identity::ZERO);
    let _: UserTableHandle<'_> = <UserTableAccessor as TableAccessor<RemoteTables>>::get(&ctx.db);
    let _: MessageTableHandle<'_> = <MessageTableAccessor as TableAccessor<RemoteTables>>::get(&ctx.db);
    let _ = <RemoteTables as UserTableAccess>::user(&ctx.db);
    let _ = <RemoteTables as MessageTableAccess>::message(&ctx.db);
}

// Query builder: the per-table traits, and the column structs through closures, which is how users reach them.
// (Today `UserCols` is only nameable as `module_bindings::user_type::UserCols`; that path is one of the
// internal paths that module-shaped bindings do not keep.)
fn query_builder(ctx: &DbConnection) {
    let _: SubscriptionHandle = ctx
        .subscription_builder()
        .add_query(|q| <_ as userQueryTableAccess>::user(&q.from))
        .add_query(|q| <_ as messageQueryTableAccess>::message(&q.from))
        .add_query(|q| q.from.user().filter(|cols| cols.online.eq(true)).build())
        .add_query(|q| q.from.message().filter(|cols| cols.text.eq("hi".to_string())).build())
        .add_query(|q| {
            q.from
                .user()
                .left_semijoin(q.from.user(), |a, b| a.identity.eq(b.identity))
                .build()
        })
        .subscribe();
}

// Reducers: the traits, `_then` with an explicitly typed callback, and the `Reducer` enum.
fn on_set_name(_ctx: &ReducerEventContext, _res: Result<Result<(), String>, InternalError>) {}
fn reducers(ctx: &DbConnection) {
    <RemoteReducers as set_name>::set_name(&ctx.reducers, "a".into()).unwrap();
    <RemoteReducers as send_message>::send_message(&ctx.reducers, "b".into()).unwrap();
    ctx.reducers.set_name_then("c".into(), on_set_name).unwrap();
    ctx.reducers.send_message_then("d".into(), |_ctx, _res| {}).unwrap();
    let r = Reducer::SetName { name: "e".into() };
    match r.clone() {
        Reducer::SendMessage { text } => drop(text),
        Reducer::SetName { name } => drop(name),
    }
    assert_eq!(r.clone(), r);
}

// Event contexts and the event types they carry.
fn contexts(
    e: &EventContext,
    r: &ReducerEventContext,
    p: &ProcedureEventContext,
    s: &SubscriptionEventContext,
    err: &ErrorContext,
) {
    let _: &Event<Reducer> = &e.event;
    let _: &ReducerEvent<Reducer> = &r.event;
    let _: &Option<spacetimedb_sdk::Error> = &err.event;
    let _: (&RemoteTables, &RemoteReducers, &RemoteProcedures) = (&e.db, &e.reducers, &e.procedures);
    let _ = (&p.db, &s.db, &r.db, &err.db);
}

// Connection, module, and the `RemoteDbContext` alias trait.
fn connection() -> DbConnectionBuilder<RemoteModule> {
    DbConnection::builder()
}
fn generic_over_contexts(ctx: &impl RemoteDbContext) -> usize {
    ctx.db().user().iter().count()
}
fn module_types(c: &DbConnection, s: &SubscriptionEventContext) -> usize {
    generic_over_contexts(c) + generic_over_contexts(s)
}
fn connection_methods(c: &DbConnection) {
    let _ = c.frame_tick();
    let _ = c.advance_one_message();
    let _: std::thread::JoinHandle<()> = c.run_threaded();
    drop(c.run_async());
    let _ = c.disconnect();
    let _ = (c.is_active(), c.try_identity(), c.try_connection_id());
}
